import * as Phaser from 'phaser';
import { configureGpuLayerCameraTransform } from '../../graphics/GpuLayerCameraTransform';
import { GPU_VFX_ATLAS_KEY, GpuVfxFrameId, buildGpuVfxAtlas, getGpuVfxFrame } from './GpuVfxAtlas';
import { GPU_VFX_EASE_NAMES } from './GpuVfxEase';
import { GPU_VFX_EFFECTS, type GpuVfxEffectId, type GpuVfxImportance } from './GpuVfxEffects';
import {
  GPU_VFX_NO_FRAME_ANIMATION,
  getGpuVfxFrameAnimation,
} from './GpuVfxFrameAnimations';
import { GPU_VFX_DEAD_MEMBER, gpuVfxEasedBase, writeGpuVfxMember } from './GpuVfxMember';
import { GpuVfxEase, isLinearGpuVfxEase } from './GpuVfxEase';
import { GPU_VFX_NO_SLOT, GpuVfxPool, type GpuVfxPoolStats } from './GpuVfxPool';
import { GpuVfxProfiler, type GpuVfxCompanionCounters, type GpuVfxReport } from './GpuVfxProfiler';
import { GpuVfxQuality } from './GpuVfxQuality';
import { GPU_VFX_LANES, GpuVfxLaneId, type GpuVfxLaneSpec } from './GpuVfxRenderLanes';
import type { GpuVfxSpawnSpec } from './GpuVfxSpawnSpec';
import { GpuFlightRibbonStore, type FlightRibbonHandle, type FlightRibbonStyle } from './GpuFlightRibbon';
import { createFlightRibbonLayer } from './GpuFlightRibbonLayer';
import type { ProjectileTrailSegment } from '../../projectile/ProjectileFlightPath';

/**
 * GpuVfxSystem – das gemeinsame GPU-VFX-Backend einer Szene.
 *
 * Effektcontroller entscheiden weiterhin *wann*, *wo*, *wie oft* und *mit welcher semantischen
 * Konfiguration* ein Partikel entsteht. Alles danach liegt hier: Lane-Auswahl, Slot-Vergabe,
 * Member-Konfiguration, Lebenszeit, Source-Lifecycle, Quality, Admission, Ablation,
 * Idle-Sichtbarkeit und Profiling.
 *
 * Ein Controller legt damit weder eigene `SpriteGPULayer` an noch besitzt er einen eigenen Pool,
 * und er sieht keine Phaser-GPU-Interna mehr.
 *
 * ## Reihenfolge in `update()`
 *
 * Erst stilllegen, dann emittieren – das ist Vertrag. Der Pool vergibt ausschliesslich freie
 * Slots; ein Spawn vor dem Retire-Sweep wuerde sonst unnoetig als Kapazitaets-Verwurf abgewiesen.
 * Effekte melden ihren Emissions-Tick deshalb hier an, statt selbst pro Frame gerufen zu werden.
 *
 * ## Sichtbarkeit
 *
 * Ein geprimter Layer zeichnet `memberCount` Instanzen, auch wenn kein Partikel lebt. Lanes ohne
 * lebende Member werden deshalb unsichtbar geschaltet. Ablation und Idle teilen sich genau einen
 * Resolver, damit nicht zwei Schreiber um `visible` kaempfen; die Ablation hat Vorrang.
 */

/**
 * Admission-Control einer Lane.
 *
 * Die obersten `reserveCritical` Slots nimmt nur `critical` an – eine rein logische Reserve auf
 * `liveCount`, kein physisch reservierter Indexbereich. Ein reservierter Bereich wuerde den Ring
 * fragmentieren und damit die Slot-Lokalitaet der Buffer-Uploads verschlechtern.
 *
 * Bewusst keine Auslastungsschwellen (60/80 %): die haengen an der frei gewaehlten Kapazitaet,
 * und auf einer geteilten Lane wuerde ein viel emittierender Effekt fremde Effekte mitdrosseln.
 */
export function admitGpuVfxSpawn(
  liveCount: number,
  capacity: number,
  reserveCritical: number,
  importance: GpuVfxImportance,
): boolean {
  if (liveCount >= capacity) return false;
  if (importance === 'critical' || reserveCritical <= 0) return true;
  return liveCount < capacity - reserveCritical;
}

/** Wird pro Renderframe gerufen, nachdem abgelaufene Member stillgelegt wurden. */
export type GpuVfxEmissionTick = (deltaMs: number, nowMs: number) => void;
export type GpuVfxDiagnosticEventSink = (type: string, fields?: Record<string, unknown>) => void;

/** Rueckgabe von `createSource()`, wenn die Source-Tabelle erschoepft ist. */
export const GPU_VFX_NO_SOURCE_HANDLE = -1;

/** Reused by controllers; a recycled pool slot cannot be addressed with an old handle. */
export interface GpuVfxMemberHandle {
  lane: number; slot: number; version: number; generation: number;
  lifeMs: number; linear: boolean;
}
export const createGpuVfxMemberHandle = (): GpuVfxMemberHandle => ({
  lane: -1, slot: -1, version: 0, generation: -1, lifeMs: 0, linear: true,
});

export type GpuVfxShaderWarmupState = 'inactive' | 'pending' | 'complete' | 'failed';

/**
 * Gleichzeitig lebende Quellen ueber alle Effekte. Grosszuegig bemessen: Raketen sind mit Abstand
 * am zahlreichsten und teilen sich fuer den Rauch ohnehin eine Quelle.
 */
const MAX_SOURCES = 1024;

const SOURCE_FREE   = 0;
const SOURCE_KILL   = 1;
const SOURCE_LINGER = 2;

interface GpuVfxLane {
  readonly spec: GpuVfxLaneSpec;
  readonly layer: Phaser.GameObjects.SpriteGPULayer;
  readonly pool: GpuVfxPool;
  visible: boolean;
  lastTimeElapsed: number;
}

export class GpuVfxSystem {
  private readonly scene: Phaser.Scene;
  readonly flightRibbons: GpuFlightRibbonStore;
  private readonly ribbonLayer: Phaser.GameObjects.Image | null;
  private flightPeak = 0;
  private readonly lanes: GpuVfxLane[] = [];
  private readonly ticks: GpuVfxEmissionTick[] = [];
  private readonly laneStats: GpuVfxPoolStats[] = [];
  readonly quality: GpuVfxQuality;
  private readonly profiler = new GpuVfxProfiler();
  private diagnosticEventSink: GpuVfxDiagnosticEventSink | null = null;
  private readonly highUtilizationState: boolean[] = [];

  /** `SOURCE_FREE` heisst frei; sonst der Release-Modus des Effekts, der sie angelegt hat. */
  private readonly sourceMode = new Uint8Array(MAX_SOURCES);
  private readonly sourceFreeList = new Int32Array(MAX_SOURCES);
  private sourceFreeCount = MAX_SOURCES;

  /** Gemeinsame monotone Uhr fuer Slot-Lebenszeiten, gleich getaktet mit den GPU-Animationen. */
  private clockMs = 0;
  private readonly transformData = new Uint32Array(9);
  private readonly transformFloats = new Float32Array(this.transformData.buffer);
  private readonly transformMask = [1, 1, 0, 0, 1, 1, 0, 0, 1];
  private suppressed = false;
  private readonly activeLanes = new Uint8Array(GPU_VFX_LANES.length);
  private generation = 0;
  /**
   * Pre-render cursor for the real SpriteGPULayer shader programs.  The cursor is deliberately
   * kept here, next to the layer owner: constructing a layer only creates its RenderNode, while
   * Phaser compiles the final feature combination on the first `run()`.
   */
  private shaderWarmupLane = 0;
  private shaderWarmupActive = false;
  private shaderWarmupState: GpuVfxShaderWarmupState = 'inactive';
  private shaderWarmupWarningIssued = false;
  private shaderWarmupShutdownRegistered = false;
  private readonly stopShaderWarmupOnShutdown = (): void => { this.stopShaderWarmup(); };
  private readonly runShaderWarmup = (): void => {
    if (!this.shaderWarmupActive || this.shaderWarmupLane >= this.lanes.length) return;

    const renderer = this.scene.renderer as Phaser.Renderer.WebGL.WebGLRenderer;
    if (!renderer.baseDrawingContext || !this.scene.cameras.main) {
      this.failShaderWarmup('Renderer-Kontext oder Hauptkamera ist nicht mehr verfuegbar.');
      return;
    }

    const lane = this.lanes[this.shaderWarmupLane];
    // `getClone()` copies the base state. The next camera render obtains another clone from the
    // untouched base context, so the probe's color mask/scissor cannot leak into the real frame.
    const context = renderer.baseDrawingContext.getClone();
    context.setCamera(this.scene.cameras.main);
    context.setAutoClear(false, false, false);
    // The draw must reach SubmitterSpriteGPULayer.run(), but must not alter the current frame.
    // A 1x1 scissor also avoids rasterizing the primed (dead) member buffer at full size.
    context.setColorWritemask(false, false, false, false);
    context.setScissorEnable(true);
    context.setScissorBox(0, 0, 1, 1);

    try {
      lane.layer.submitterNode.run(context);
      // With KHR_parallel_shader_compile Phaser returns null while the link is pending. Keep
      // this lane selected until its actual program suite is resident in the ProgramManager.
      if (lane.layer.submitterNode.programManager.getCurrentProgramSuite()) {
        this.shaderWarmupLane += 1;
        if (this.shaderWarmupLane >= this.lanes.length) {
          this.shaderWarmupState = 'complete';
          this.stopShaderWarmup();
        }
      }
    } catch (error) {
      // Shader warmup is an optional presentation optimization. A renderer/platform that cannot
      // execute the isolated probe must continue with the normal, authoritative render path.
      this.failShaderWarmup(error);
    } finally {
      context.release();
    }
  };
  /** Invalidates not-yet-emitted commands when live effects are forcibly cleared. */
  get emissionGeneration(): number { return this.generation; }

  constructor(scene: Phaser.Scene) {
    this.scene = scene;
    // Der Atlas muss vollstaendig sein, bevor die erste Lane entsteht: `frameDataTexture` wird im
    // Konstruktor des Layers gebaut, spaeter ergaenzte Frames existieren fuer den Shader nicht.
    buildGpuVfxAtlas(scene);
    this.quality = new GpuVfxQuality(scene);

    for (const spec of GPU_VFX_LANES) {
      const layer = scene.add.spriteGPULayer(GPU_VFX_ATLAS_KEY, spec.capacity);
      configureGpuLayerCameraTransform(layer);
      // Alle Lanes teilen sich den Atlas; der Name ist danach das einzige Unterscheidungsmerkmal
      // in Debugger und Diagnose.
      layer.name = spec.label;
      layer.setBlendMode(spec.blendMode);
      layer.setDepth(spec.depth);
      if (spec.gravity !== undefined) layer.gravity = spec.gravity;
      // Ein erstmals auftauchender Ease-Typ laesst Shader und FrameData neu bauen; hier
      // vorgewaermt passiert das nie im Spielverlauf.
      for (const ease of spec.eases) layer.setAnimationEnabled(GPU_VFX_EASE_NAMES[ease], true);
      if (spec.frameAnimations && spec.frameAnimations.length > 0) {
        const animations: Phaser.Types.GameObjects.SpriteGPULayer.SetAnimation[] = [];
        for (const animationId of spec.frameAnimations) {
          const animation = getGpuVfxFrameAnimation(animationId);
          animations.push({
            name: animation.name,
            frames: animation.frames.map((frameId) => getGpuVfxFrame(frameId).name),
            // Spawn-Member ueberschreiben die Dauer mit ihrer Lifetime.
            duration: 1,
          });
        }
        layer.setAnimations(animations);
      }

      const pool = new GpuVfxPool(layer, spec.capacity, spec.label, MAX_SOURCES);
      pool.prime(GPU_VFX_DEAD_MEMBER);
      // Leere Lanes zeichnen sonst ihre volle Kapazitaet an Instanzen.
      layer.setVisible(false);

      this.lanes.push({ spec, layer, pool, visible: false, lastTimeElapsed: layer.timeElapsed });
    }

    for (let index = 0; index < MAX_SOURCES; index += 1) this.sourceFreeList[index] = index;
    const flightLane = this.lanes[GpuVfxLaneId.FlightSignature];
    const frames = [GpuVfxFrameId.FlightCoreStrip, GpuVfxFrameId.FlightWakeStrip].map(id => {
      const frame = getGpuVfxFrame(id);
      return { u: (frame.u0 + frame.u1) / 2, top: frame.v0, bottom: frame.v1 };
    });
    this.flightRibbons = new GpuFlightRibbonStore({
      admit: effect => admitGpuVfxSpawn(this.flightLiveCount(), flightLane.spec.capacity,
        flightLane.spec.reserveCritical, GPU_VFX_EFFECTS[effect].importance),
      attempt: effect => this.profiler.recordAttempt(effect),
      spawn: effect => { this.profiler.recordSpawn(effect); this.flightPeak = Math.max(this.flightPeak, this.flightLiveCount()); },
      drop: effect => this.profiler.recordCapacityDrop(effect),
    }, [frames[0], frames[1]], flightLane.spec.capacity);
    this.ribbonLayer = createFlightRibbonLayer(scene, this.flightRibbons, flightLane.spec.depth, () => this.clockMs);

    // Register after all lanes exist. Each PRE_RENDER pass probes one lane through its actual
    // SpriteGPULayer submitter, moving first-use shader work out of the combat path.
    this.startShaderWarmup();
  }

  private startShaderWarmup(): void {
    const renderer = this.scene.renderer as Phaser.Renderer.WebGL.WebGLRenderer | undefined;
    const events = this.scene.events;
    if (!renderer || !('baseDrawingContext' in renderer) || !renderer.baseDrawingContext
      || !this.scene.cameras.main || !events || typeof events.on !== 'function') return;
    this.shaderWarmupLane = 0;
    this.shaderWarmupActive = true;
    this.shaderWarmupState = 'pending';
    events.on(Phaser.Scenes.Events.PRE_RENDER, this.runShaderWarmup, this);
    events.once(Phaser.Scenes.Events.SHUTDOWN, this.stopShaderWarmupOnShutdown, this);
    this.shaderWarmupShutdownRegistered = true;
  }

  private stopShaderWarmup(): void {
    if (this.shaderWarmupActive) {
      this.shaderWarmupActive = false;
      this.scene.events.off(Phaser.Scenes.Events.PRE_RENDER, this.runShaderWarmup, this);
    }
    if (this.shaderWarmupShutdownRegistered) {
      this.shaderWarmupShutdownRegistered = false;
      this.scene.events.off(Phaser.Scenes.Events.SHUTDOWN, this.stopShaderWarmupOnShutdown, this);
    }
  }

  private failShaderWarmup(reason: unknown): void {
    this.shaderWarmupState = 'failed';
    if (!this.shaderWarmupWarningIssued) {
      this.shaderWarmupWarningIssued = true;
      console.warn(
        '[GpuVfxSystem] SpriteGPU-Shader-Warmup fehlgeschlagen; erste Nutzung nutzt den normalen Renderpfad.',
        reason,
      );
      this.diagnosticEventSink?.('gpu:vfx_shader_warmup_failed');
    }
    this.stopShaderWarmup();
  }

  /** No pending warmup work remains; failed warmup deliberately falls back to normal rendering. */
  isShaderWarmupComplete(): boolean {
    return this.shaderWarmupState !== 'pending';
  }

  getShaderWarmupState(): GpuVfxShaderWarmupState {
    return this.shaderWarmupState;
  }

  createFlightRibbon(source: number, style: FlightRibbonStyle): FlightRibbonHandle | null {
    return this.flightRibbons.create(source, style);
  }
  appendFlightRibbon(handle: FlightRibbonHandle, segment: ProjectileTrailSegment, wake: boolean): void {
    if (!this.suppressed) this.flightRibbons.append(handle, segment, this.clockMs, wake, this.quality.getFactor('standard'));
  }
  breakFlightRibbon(handle: FlightRibbonHandle): void { this.flightRibbons.break(handle); }
  endFlightRibbon(handle: FlightRibbonHandle): void { this.flightRibbons.end(handle); }
  private flightLiveCount(): number {
    return this.lanes[GpuVfxLaneId.FlightSignature].pool.getLiveCount() + (this.flightRibbons?.liveCount ?? 0);
  }

  // ── Spawn-Schnittstelle ────────────────────────────────────────────────────

  /**
   * Ein Spec je Controller, einmalig ausgegeben und danach nur noch mutiert. Vorbelegt mit Lane
   * und Frame des Effekts; Werte, die jeder Effekt ohnehin setzt, stehen auf neutralen Defaults.
   */
  createSpec(effect: GpuVfxEffectId): GpuVfxSpawnSpec {
    const spec = GPU_VFX_EFFECTS[effect];
    return {
      effect,
      lane: spec.lane,
      frame: spec.frame,
      frameAnimation: GPU_VFX_NO_FRAME_ANIMATION,
      frameAnimationDurationScale: 1,
      lifeMs: 0,
      x: 0, y: 0, vx: 0, vy: 0,
      positionEase: 0,
      yMode: 0, gravityFactor: 1,
      rotation: 0, angularVelocity: 0, rotationEase: 0,
      scaleStart: 1, scaleEnd: 1, scaleEase: 0,
      // Neutral: uniforme Skalierung und voller Tint – exakt das Verhalten vor diesen Feldern.
      stretchStart: 1, stretchEnd: 1,
      alphaStart: 1, alphaEnd: 0, alphaEase: 0,
      tint: 0xffffff,
      tintBlendStart: 1, tintBlendEnd: 1,
    };
  }

  /**
   * Erzeugt genau ein Partikel. `sourceIndex` darf `GPU_VFX_NO_SOURCE_HANDLE` sein – der Member
   * lebt dann einfach aus und gehoert zu niemandem.
   *
   * Liefert `false`, wenn der Spawn verworfen wurde; getrennt gezaehlt nach Kapazitaet und
   * kritischer Reserve.
   */
  spawn(spec: GpuVfxSpawnSpec, sourceIndex: number, nowMs: number, ageMs = 0, out?: GpuVfxMemberHandle): boolean {
    if (out) out.slot = -1;
    ageMs = Math.max(0, ageMs);
    if (!Number.isFinite(ageMs) || ageMs >= spec.lifeMs) return false;
    const lane = this.lanes[spec.lane];
    this.profiler.recordAttempt(spec.effect);
    if (!lane) return false;

    if (!admitGpuVfxSpawn(
      spec.lane === GpuVfxLaneId.FlightSignature ? this.flightLiveCount() : lane.pool.getLiveCount(),
      lane.spec.capacity,
      lane.spec.reserveCritical,
      GPU_VFX_EFFECTS[spec.effect].importance,
    )) {
      // Auf beiden Ebenen buchen: die Lane sieht ihre Auslastung, der Effekt seinen Verlust.
      lane.pool.recordCapacityDrop();
      this.profiler.recordCapacityDrop(spec.effect);
      return false;
    }

    const slot = lane.pool.acquire(sourceIndex, nowMs, spec.lifeMs - ageMs);
    if (slot === GPU_VFX_NO_SLOT) {
      this.profiler.recordCapacityDrop(spec.effect);
      return false;
    }

    const frameAnimation = spec.frameAnimation === GPU_VFX_NO_FRAME_ANIMATION
      ? null
      : getGpuVfxFrameAnimation(spec.frameAnimation);
    const member = writeGpuVfxMember(spec, getGpuVfxFrame(spec.frame), frameAnimation);
    member.creationTime = lane.layer.timeElapsed - ageMs;
    lane.layer.editMember(
      slot,
      // Phaser 4.2.1 verarbeitet hier ein MemberAnimation-Objekt (SpriteGPULayer.js), waehrend
      // seine d.ts fuer `animation` noch nur string|number nennt.
      member as unknown as Partial<Phaser.Types.GameObjects.SpriteGPULayer.Member>,
    );
    this.profiler.recordSpawn(spec.effect);
    if (out && spec.yMode !== GpuVfxEase.Gravity && spec.angularVelocity === 0) {
      out.lane = spec.lane; out.slot = slot; out.version = lane.pool.getVersion(slot);
      out.generation = this.generation; out.lifeMs = spec.lifeMs;
      out.linear = isLinearGpuVfxEase(spec.positionEase);
    }
    if (spec.lane === GpuVfxLaneId.FlightSignature) this.flightPeak = Math.max(this.flightPeak, this.flightLiveCount());
    // Auch Spawns ausserhalb des Emissions-Ticks muessen ihre Lane sofort sichtbar machen,
    // sonst faellt das erste Partikel eines Bursts einen Frame lang aus.
    this.applyVisibility(lane);
    return true;
  }

  isMemberLive(handle: GpuVfxMemberHandle): boolean {
    return handle.generation === this.generation
      && !!this.lanes[handle.lane]?.pool.isLiveVersion(handle.slot, handle.version);
  }

  /** Only x/y base + amplitude and static rotation. Handles exclude gravity/angular animation. */
  updateTransform(handle: GpuVfxMemberHandle, x: number, y: number, vx: number, vy: number, rotation: number): boolean {
    if (!this.isMemberLive(handle)) return false;
    if (!Number.isFinite(x + y + vx + vy + rotation)) return false;
    const ax = vx * handle.lifeMs / 1000, ay = vy * handle.lifeMs / 1000;
    const data = this.transformFloats;
    data[0] = handle.linear ? x : gpuVfxEasedBase(x, ax); data[1] = ax;
    data[4] = handle.linear ? y : gpuVfxEasedBase(y, ay); data[5] = ay;
    data[8] = rotation;
    return this.lanes[handle.lane].pool.patchVersion(handle.slot, handle.version, this.transformData, this.transformMask);
  }

  releaseMember(handle: GpuVfxMemberHandle): void {
    if (this.isMemberLive(handle)) this.lanes[handle.lane].pool.releaseVersion(handle.slot, handle.version);
    handle.slot = -1;
  }

  /** Ein vom Controller unterdrueckter Spawn (Qualitaetsfaktor) – zaehlt getrennt. */
  recordQualityDrop(effect: GpuVfxEffectId, count = 1): void {
    for (let n = 0; n < count; n += 1) this.profiler.recordQualityDrop(effect);
  }

  // ── Source-Lifecycle ───────────────────────────────────────────────────────

  /**
   * Legt eine Quelle an. Der Release-Modus kommt aus dem Effekt-Manifest: `kill-with-source`
   * legt die Member beim Freigeben still, `linger` loest sie nur von der Quelle.
   */
  createSource(effect: GpuVfxEffectId): number {
    if (this.sourceFreeCount === 0) return GPU_VFX_NO_SOURCE_HANDLE;
    this.sourceFreeCount -= 1;
    const index = this.sourceFreeList[this.sourceFreeCount];
    this.sourceMode[index] = GPU_VFX_EFFECTS[effect].release === 'linger' ? SOURCE_LINGER : SOURCE_KILL;
    return index;
  }

  /**
   * Gibt eine Quelle frei. Bei `linger` werden ihre Member vorher von ihr geloest – erst das
   * macht das Recyceln des Index sicher, weil ein spaeterer Besitzer sonst fremde Member
   * stilllegen koennte.
   */
  releaseSource(sourceIndex: number): void {
    if (sourceIndex < 0 || sourceIndex >= MAX_SOURCES) return;
    const mode = this.sourceMode[sourceIndex];
    if (mode === SOURCE_FREE) return;

    this.flightRibbons.clearSource(sourceIndex, mode === SOURCE_LINGER);
    this.flightRibbons.flush();
    this.applyRibbonVisibility();

    for (let index = 0; index < this.lanes.length; index += 1) {
      const pool = this.lanes[index].pool;
      if (mode === SOURCE_LINGER) pool.detachSource(sourceIndex);
      else pool.releaseSource(sourceIndex);
    }

    this.sourceMode[sourceIndex] = SOURCE_FREE;
    this.sourceFreeList[this.sourceFreeCount] = sourceIndex;
    this.sourceFreeCount += 1;
  }

  /**
   * Legt alle Member einer Quelle still, laesst die Quelle selbst aber bestehen. Fuer
   * langlebige, geteilte Quellen (etwa den Raketenrauch, den sich alle Raketen teilen), deren
   * Material beim Rundenteardown verschwinden soll, ohne dass der Controller einen neuen
   * Handle beschaffen muss.
   */
  clearSource(sourceIndex: number): void {
    if (sourceIndex < 0 || sourceIndex >= MAX_SOURCES) return;
    if (this.sourceMode[sourceIndex] === SOURCE_FREE) return;
    this.flightRibbons.clearSource(sourceIndex);
    this.flightRibbons.flush();
    this.applyRibbonVisibility();
    for (let index = 0; index < this.lanes.length; index += 1) {
      const lane = this.lanes[index];
      lane.pool.releaseSource(sourceIndex);
      this.applyVisibility(lane);
    }
  }

  // ── Frame-Lifecycle ────────────────────────────────────────────────────────

  /** Meldet den Emissions-Tick eines Effekts an. Reihenfolge der Anmeldung = Reihenfolge im Frame. */
  registerEmission(tick: GpuVfxEmissionTick): () => void {
    this.ticks.push(tick);
    return () => {
      const index = this.ticks.indexOf(tick);
      if (index >= 0) this.ticks.splice(index, 1);
    };
  }

  setDiagnosticEventSink(sink: GpuVfxDiagnosticEventSink | null): void {
    this.diagnosticEventSink = sink;
  }

  /** Aktueller Stand der Partikeluhr; identisch mit dem, was `update()` den Ticks uebergibt. */
  now(): number {
    return this.clockMs;
  }

  isSuppressed(): boolean {
    return this.suppressed;
  }

  /**
   * Pro Renderframe aufzurufen, unabhaengig von Rolle und Netzzustand: die bisherigen Emitter
   * liefen autonom weiter, auch wenn gerade kein neuer Zustand ankam.
   */
  update(deltaMs: number): void {
    this.clockMs += deltaMs;
    this.flightRibbons.retire(this.clockMs);

    for (let index = 0; index < this.lanes.length; index += 1) {
      const lane = this.lanes[index];
      lane.pool.beginFrame();
      this.handleTimeWrap(lane);
      lane.pool.retireExpired(this.clockMs);
    }

    // Waehrend der Ablation ruhen Rendering *und* Scheduler. Die Flow-Countdowns der Effekte
    // bleiben unangetastet, damit beim Segmentende nichts nachgeholt wird.
    if (!this.suppressed) {
      for (let index = 0; index < this.ticks.length; index += 1) {
        this.ticks[index](deltaMs, this.clockMs);
      }
    }

    this.flightRibbons.flush();
    this.applyRibbonVisibility();
    this.activeLanes.fill(0);
    for (let index = 0; index < this.lanes.length; index += 1) {
      const lane = this.lanes[index];
      this.applyVisibility(lane);
      const liveCount = index === GpuVfxLaneId.FlightSignature ? this.flightLiveCount() : lane.pool.getLiveCount();
      if (!this.suppressed && liveCount > 0) this.activeLanes[index] = 1;
      const capacity = Math.max(1, lane.pool.getCapacity());
      const high = liveCount / capacity >= 0.9;
      if (high && !this.highUtilizationState[index]) {
        this.diagnosticEventSink?.('gpu:vfx_high_utilization', {
          lane: lane.spec.label,
          liveCount,
          capacity,
          utilization: liveCount / capacity,
        });
      }
      this.highUtilizationState[index] = high;
    }
    this.profiler.recordFrame(this.activeLanes);
  }

  /**
   * Ablations-Hook. GPU-Zeit laesst sich nicht anhalten, deshalb ist das Stilllegen der
   * laufenden Member das Aequivalent zum `setActive(false)` der klassischen Emitter.
   */
  setSuppressed(suppressed: boolean): void {
    if (this.suppressed === suppressed) return;
    this.suppressed = suppressed;
    if (suppressed) this.generation++;
    if (suppressed) this.flightRibbons.clear();
    if (suppressed) this.flightRibbons.flush();
    this.applyRibbonVisibility();
    for (const lane of this.lanes) {
      if (suppressed) lane.pool.releaseAll();
      this.applyVisibility(lane);
    }
  }

  releaseAll(): void {
    this.generation++;
    this.flightRibbons.clear();
    this.flightRibbons.flush();
    this.applyRibbonVisibility();
    for (const lane of this.lanes) {
      lane.pool.releaseAll();
      this.applyVisibility(lane);
    }
    this.quality.resetAllCarry();
  }

  destroy(): void {
    this.stopShaderWarmup();
    this.releaseAll();
    this.ribbonLayer?.destroy();
    for (const lane of this.lanes) lane.layer.destroy();
    this.lanes.length = 0;
    this.ticks.length = 0;
    this.quality.destroy();
  }

  // ── Diagnose ───────────────────────────────────────────────────────────────

  /** Live-Ansicht fuer das Overlay: Lane-Label -> Poolzustand. */
  getStats(): Record<string, GpuVfxPoolStats> | null {
    if (this.lanes.length === 0) return null;
    const stats: Record<string, GpuVfxPoolStats> = {};
    for (const lane of this.lanes) stats[lane.spec.label] = this.getLaneStats(lane.spec.id)!;
    return stats;
  }

  /** Low-cost cumulative counters used by the 4-Hz Companion series. */
  getCompanionCounters(): GpuVfxCompanionCounters {
    return this.profiler.getCompanionCounters();
  }

  /** Vollstaendiger Zwei-Ebenen-Report fuer den Performance-Export. */
  buildReport(): GpuVfxReport {
    this.laneStats.length = 0;
    for (const lane of this.lanes) this.laneStats.push(this.getLaneStats(lane.spec.id)!);
    return this.profiler.buildReport(this.laneStats);
  }

  /** Neues Messfenster: Effekt- und Lane-Zaehler beginnen gemeinsam bei null. */
  resetProfiling(): void {
    this.profiler.reset();
    for (const lane of this.lanes) lane.pool.resetStats();
    this.flightRibbons.resetStats();
    this.flightPeak = this.flightLiveCount();
    this.highUtilizationState.fill(false);
  }

  getLaneStats(id: GpuVfxLaneId): GpuVfxPoolStats | null {
    const stats = this.lanes[id]?.pool.getStats();
    if (!stats) return null;
    if (id !== GpuVfxLaneId.FlightSignature) return stats;
    const ribbon = this.flightRibbons.stats();
    return { ...stats, liveCount: stats.liveCount + ribbon.liveCount, peakLive: this.flightPeak,
      rearms: stats.rearms + ribbon.rearms, retirements: stats.retirements + ribbon.retirements,
      capacityDrops: stats.capacityDrops + ribbon.capacityDrops, segmentsTouched: stats.segmentsTouched + ribbon.segmentsTouched };
  }

  private applyRibbonVisibility(): void { this.ribbonLayer?.setVisible(!this.suppressed && this.flightRibbons.liveCount > 0); }

  // ── Interna ────────────────────────────────────────────────────────────────

  /**
   * Der eine Resolver fuer `visible`. Ablation gewinnt immer; danach entscheidet allein, ob die
   * Lane ueberhaupt etwas zu zeigen hat. Geschrieben wird nur bei einem echten Wechsel.
   */
  private applyVisibility(lane: GpuVfxLane): void {
    const want = !this.suppressed && lane.pool.getLiveCount() > 0;
    if (want === lane.visible) return;
    lane.visible = want;
    lane.layer.setVisible(want);
  }

  /**
   * Der `ElapseTimer` eines Layers springt nach `timeElapsedResetPeriod` (eine Stunde) auf null
   * zurueck, ohne die `creationTime` der Member mitzuziehen. Deren Animationen wuerden dann
   * schlagartig weit ueber ihr Ende hinaus extrapolieren – bei ADD ein bildschirmfuellender
   * Blitz, bis der Retire-Sweep nachkommt. Beim Ruecksprung deshalb sofort alles stilllegen.
   */
  private handleTimeWrap(lane: GpuVfxLane): void {
    const timeElapsed = lane.layer.timeElapsed;
    if (timeElapsed < lane.lastTimeElapsed) lane.pool.releaseAll();
    lane.lastTimeElapsed = timeElapsed;
  }
}
